using System.Text;
using static CodeGen.Fast.Model;

namespace CodeGen.Fast;

internal static class Emit
{
    private const string Header = """
        // <auto-generated/>
        // Generated by CodeGen.Fast from the EngineeringUnits unit definitions - changes will be overwritten!
        #nullable enable

        """;

    // SI = value * mul / div + offset. Written out so the JIT sees constants, and bit-identical to UnitTypebase.ToSI/FromSI
    private static string ToSI(UnitDef u, string v)
    {
        var s = v;
        if (u.Multiplier != 1) s = $"{s} * {Num(u.Multiplier)}";
        if (u.Divisor != 1) s = $"{s} / {Num(u.Divisor)}";
        if (u.Offset != 0) s = $"({s}) + {Num(u.Offset)}";
        return s;
    }

    private static string FromSI(UnitDef u, string si)
    {
        var s = u.Offset != 0 ? $"({si} - {Num(u.Offset)})" : si;
        if (u.Multiplier != 1) s = $"{s} / {Num(u.Multiplier)}";
        if (u.Divisor != 1) s = $"{s} * {Num(u.Divisor)}";
        return s;
    }

    public static string Quantity(QuantityDef q, IReadOnlyList<QuantityDef> aliases, IReadOnlySet<string> implicitAliases)
    {
        var T = q.Name;
        var U = $"{T}Unit";
        var sb = new StringBuilder(Header);

        sb.AppendLine($$"""
            using System;
            using System.Collections.Generic;
            using System.Text.Json;
            using System.Text.Json.Serialization;
            using EngineeringUnits.Units.Fast;

            namespace EngineeringUnits.Fast;

            /// <summary>{{T}} [{{q.Units[0].Symbol}}] stored as a single double in SI units. Unit checks happen at compile time (EngineeringUnits.Fast analyzer).</summary>
            [UnitDimension({{q.Dim.AttributeArgs}})]
            [JsonConverter(typeof({{T}}JsonConverter))]
            [System.ComponentModel.TypeConverter(typeof(QuantityTypeConverter<{{T}}>))]
            public readonly partial struct {{T}} : IQuantity<{{T}}>, IEquatable<{{T}}>, IComparable<{{T}}>, IComparable, IFormattable,
                System.Numerics.IAdditionOperators<{{T}}, {{T}}, {{T}}>,
                System.Numerics.ISubtractionOperators<{{T}}, {{T}}, {{T}}>,
                System.Numerics.IUnaryNegationOperators<{{T}}, {{T}}>,
                System.Numerics.IUnaryPlusOperators<{{T}}, {{T}}>,
                System.Numerics.IMultiplyOperators<{{T}}, double, {{T}}>,
                System.Numerics.IDivisionOperators<{{T}}, double, {{T}}>,
                System.Numerics.IComparisonOperators<{{T}}, {{T}}, bool>,
                System.Numerics.IAdditiveIdentity<{{T}}, {{T}}>
            {
                private readonly double _si;

                private {{T}}(double si) => _si = si;

                /// <summary>Creates a {{T}} from a value in the given unit.</summary>
                public {{T}}(double value, {{U}} unit) => _si = unit.ToSI(value);

                /// <summary>The value in SI units [{{q.Units[0].Symbol}}].</summary>
                public double SI => _si;

                UnitTypebase IQuantity.SIUnit => {{U}}.SI;

                public static {{T}} FromSI(double si) => new(si);
                public static {{T}} From(double value, {{U}} unit) => new(unit.ToSI(value));
                // Nullable inputs, like EngineeringUnits: null in, null out
                public static {{T}}? From(double? value, {{U}} unit) => value is { } v ? From(v, unit) : null;
                public static {{T}}? FromSI(double? si) => si is { } v ? new {{T}}(v) : null;
                public double As({{U}} unit) => unit.FromSI(_si);

                public static {{T}} Zero => default;
                public static {{T}} AdditiveIdentity => default;
                public static {{T}} NaN => new(double.NaN);
                public static {{T}} PositiveInfinity => new(double.PositiveInfinity);
                public static {{T}} NegativeInfinity => new(double.NegativeInfinity);
                public static {{T}} MaxValue => new(double.MaxValue);
                public static {{T}} MinValue => new(double.MinValue);

                /// <summary>All units of {{T}}.</summary>
                public static IReadOnlyList<{{U}}> Units => {{U}}.All;

            """);

        foreach (var u in q.Units.Where(u => u.Name != "SI"))
        {
            sb.AppendLine($"    public static {T} From{u.Name}(double {u.Name}) => new({ToSI(u, u.Name)});");
            sb.AppendLine($"    public static {T}? From{u.Name}(double? {u.Name}) => {u.Name} is {{ }} v ? From{u.Name}(v) : null;");
            sb.AppendLine($"    public double {u.Name} => {FromSI(u, "_si")};");
        }

        if (q.Forwarders.Count > 0)
        {
            sb.AppendLine();
            sb.AppendLine("    // ---- Other names EngineeringUnits has for the same units (matched by value by the generator) ----");
            foreach (var (member, unit, isFactory) in q.Forwarders)
            {
                if (isFactory)
                {
                    sb.AppendLine($"    public static {T} {member}(double value) => {(unit.Name == "SI" ? "FromSI" : "From" + unit.Name)}(value);");
                    sb.AppendLine($"    public static {T}? {member}(double? value) => value is {{ }} v ? {member}(v) : null;");
                }
                else
                {
                    sb.AppendLine($"    public double {member} => {unit.Name};");
                }
            }
        }

        sb.AppendLine($$"""

                // ---- + and - : same quantity only (other quantities give an ambiguity compile error) ----
                public static {{T}} operator +({{T}} a, {{T}} b) => new(a._si + b._si);
                public static {{T}} operator -({{T}} a, {{T}} b) => new(a._si - b._si);
                // With an UnknownUnit: the analyzer checks the UnknownUnit's dimension (EUF0002)
                public static {{T}} operator +({{T}} a, UnknownUnit b) => new(a._si + b.SI);
                public static {{T}} operator +(UnknownUnit a, {{T}} b) => new(a.SI + b._si);
                public static {{T}} operator -({{T}} a, UnknownUnit b) => new(a._si - b.SI);
                public static {{T}} operator -(UnknownUnit a, {{T}} b) => new(a.SI - b._si);
                // Explicit nullable versions: the lifted operators alone are ambiguous for {{T}}? + {{T}}
                public static {{T}}? operator +({{T}}? a, {{T}} b) => a.HasValue ? new(a.GetValueOrDefault()._si + b._si) : null;
                public static {{T}}? operator +({{T}} a, {{T}}? b) => b.HasValue ? new(a._si + b.GetValueOrDefault()._si) : null;
                public static {{T}}? operator -({{T}}? a, {{T}} b) => a.HasValue ? new(a.GetValueOrDefault()._si - b._si) : null;
                public static {{T}}? operator -({{T}} a, {{T}}? b) => b.HasValue ? new(a._si - b.GetValueOrDefault()._si) : null;
                public static {{T}} operator -({{T}} a) => new(-a._si);
                public static {{T}} operator +({{T}} a) => a;

                // ---- * and / : ONE mixed operator with this type on the left. Every other quantity converts to UnknownUnit. ----
                // This keeps the operator count linear (no N^2 table) and never ambiguous; the analyzer works out the dimension.
                public static UnknownUnit operator *({{T}} a, UnknownUnit b) => new(a._si * b.SI);
                public static UnknownUnit operator /({{T}} a, UnknownUnit b) => new(a._si / b.SI);
                public static {{T}} operator *({{T}} a, double b) => new(a._si * b);
                public static {{T}} operator *(double a, {{T}} b) => new(a * b._si);
                public static {{T}} operator /({{T}} a, double b) => new(a._si / b);
                public static UnknownUnit operator /(double a, {{T}} b) => new(a / b._si);

                // ---- Comparisons ----
                public static bool operator ==({{T}} a, {{T}} b) => a._si == b._si;
                public static bool operator !=({{T}} a, {{T}} b) => a._si != b._si;
                public static bool operator <({{T}} a, {{T}} b) => a._si < b._si;
                public static bool operator >({{T}} a, {{T}} b) => a._si > b._si;
                public static bool operator <=({{T}} a, {{T}} b) => a._si <= b._si;
                public static bool operator >=({{T}} a, {{T}} b) => a._si >= b._si;
                public static bool operator ==({{T}} a, UnknownUnit b) => a._si == b.SI;
                public static bool operator !=({{T}} a, UnknownUnit b) => a._si != b.SI;
                public static bool operator <({{T}} a, UnknownUnit b) => a._si < b.SI;
                public static bool operator >({{T}} a, UnknownUnit b) => a._si > b.SI;
                public static bool operator <=({{T}} a, UnknownUnit b) => a._si <= b.SI;
                public static bool operator >=({{T}} a, UnknownUnit b) => a._si >= b.SI;
                public static bool operator ==(UnknownUnit a, {{T}} b) => a.SI == b._si;
                public static bool operator !=(UnknownUnit a, {{T}} b) => a.SI != b._si;
                public static bool operator <(UnknownUnit a, {{T}} b) => a.SI < b._si;
                public static bool operator >(UnknownUnit a, {{T}} b) => a.SI > b._si;
                public static bool operator <=(UnknownUnit a, {{T}} b) => a.SI <= b._si;
                public static bool operator >=(UnknownUnit a, {{T}} b) => a.SI >= b._si;
                // Nullable: same semantics as the lifted operators (null compares false, == only when both have a value)
                public static bool operator ==({{T}}? a, {{T}} b) => a.HasValue && a.GetValueOrDefault()._si == b._si;
                public static bool operator !=({{T}}? a, {{T}} b) => !(a == b);
                public static bool operator ==({{T}} a, {{T}}? b) => b.HasValue && a._si == b.GetValueOrDefault()._si;
                public static bool operator !=({{T}} a, {{T}}? b) => !(a == b);
                public static bool operator ==({{T}}? a, {{T}}? b) => a.HasValue ? b.HasValue && a.GetValueOrDefault()._si == b.GetValueOrDefault()._si : !b.HasValue;
                public static bool operator !=({{T}}? a, {{T}}? b) => !(a == b);
                public static bool operator <({{T}}? a, {{T}} b) => a.HasValue && a.GetValueOrDefault()._si < b._si;
                public static bool operator >({{T}}? a, {{T}} b) => a.HasValue && a.GetValueOrDefault()._si > b._si;
                public static bool operator <=({{T}}? a, {{T}} b) => a.HasValue && a.GetValueOrDefault()._si <= b._si;
                public static bool operator >=({{T}}? a, {{T}} b) => a.HasValue && a.GetValueOrDefault()._si >= b._si;
                public static bool operator <({{T}} a, {{T}}? b) => b.HasValue && a._si < b.GetValueOrDefault()._si;
                public static bool operator >({{T}} a, {{T}}? b) => b.HasValue && a._si > b.GetValueOrDefault()._si;
                public static bool operator <=({{T}} a, {{T}}? b) => b.HasValue && a._si <= b.GetValueOrDefault()._si;
                public static bool operator >=({{T}} a, {{T}}? b) => b.HasValue && a._si >= b.GetValueOrDefault()._si;

                // ---- Conversions ----
                public static implicit operator UnknownUnit({{T}} value) => new(value._si);
                /// <summary>Free at runtime - the analyzer checks the dimension at compile time (EUF0001).</summary>
                public static implicit operator {{T}}(UnknownUnit value) => new(value.SI);
                // Deliberately NO implicit {{T}}(UnknownUnit?): the null literal converts to UnknownUnit?, so "Power p = null;" would
                // compile and throw, and "cond ? x : null" would throw instead of being null. (The analyzer caught this.)

            """);

        if (q.Dim.Terms.Count == 0)
        {
            sb.AppendLine($$"""
                    // ---- Dimensionless: plain numbers mix in, like EngineeringUnits (1 - massRatio) ----
                    public static {{T}} operator +({{T}} a, double b) => new(a._si + b);
                    public static {{T}} operator +(double a, {{T}} b) => new(a + b._si);
                    public static {{T}} operator -({{T}} a, double b) => new(a._si - b);
                    public static {{T}} operator -(double a, {{T}} b) => new(a - b._si);

                """);
        }

        foreach (var alias in aliases)
        {
            var A = alias.Name;
            var conversion = implicitAliases.Contains(A)
                ? $"// Implicit, like in EngineeringUnits: {A} and {T} are two names for the same thing\n    public static implicit operator {T}({A} value) => new(value.SI);"
                : $"// Explicit: same dimension doesn't always mean the same thing (Torque vs Energy)\n    public static explicit operator {T}({A} value) => new(value.SI);";
            sb.AppendLine($$"""
                    // ---- Alias: {{A}} has the same dimension ----
                    {{conversion}}
                    public static {{T}} operator +({{T}} a, {{A}} b) => new(a._si + b.SI);
                    public static {{T}} operator -({{T}} a, {{A}} b) => new(a._si - b.SI);
                    public static bool operator ==({{T}} a, {{A}} b) => a._si == b.SI;
                    public static bool operator !=({{T}} a, {{A}} b) => a._si != b.SI;
                    public static bool operator <({{T}} a, {{A}} b) => a._si < b.SI;
                    public static bool operator >({{T}} a, {{A}} b) => a._si > b.SI;
                    public static bool operator <=({{T}} a, {{A}} b) => a._si <= b.SI;
                    public static bool operator >=({{T}} a, {{A}} b) => a._si >= b.SI;
                    // Same dimension, so {{A}}'s units work too - like EngineeringUnits' As(UnitSystem)
                    public double As({{A}}Unit unit) => unit.FromSI(_si);
                    public QuantityInUnit<{{T}}> ToUnit({{A}}Unit unit) => new(this, unit);
                    public string ToString({{A}}Unit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

                """);

            // With an implicit conversion both ways, "{T}? - {A}" could use {T}'s (T?, T) or {A}'s (A?, A) operator - ambiguous.
            // These match exactly, and behave like the (T?, T) ones they call
            if (implicitAliases.Contains(A))
            {
                foreach (var op in new[] { "+", "-" })
                    sb.AppendLine($$"""
                            public static {{T}}? operator {{op}}({{T}}? a, {{A}} b) => a {{op}} ({{T}})b;
                            public static {{T}}? operator {{op}}({{T}} a, {{A}}? b) => a {{op}} ({{T}}?)b;
                        """);
                foreach (var op in new[] { "==", "!=", "<", ">", "<=", ">=" })
                    sb.AppendLine($$"""
                            public static bool operator {{op}}({{T}}? a, {{A}} b) => a {{op}} ({{T}})b;
                            public static bool operator {{op}}({{T}} a, {{A}}? b) => a {{op}} ({{T}}?)b;
                        """);
                sb.AppendLine();
            }
        }

        sb.AppendLine($$"""
                // ---- Helpers - same names and behaviour as EngineeringUnits ----
                public {{T}} Abs() => new(Math.Abs(_si));
                /// <summary>Limits the value to [min, max]. Like EngineeringUnits: if max &lt; min the value is returned unchanged.</summary>
                public {{T}} Clamp({{T}} min, {{T}} max) => max._si < min._si ? this : new(Math.Min(Math.Max(_si, min._si), max._si));
                /// <summary>Like EngineeringUnits: a null limit is no limit.</summary>
                public {{T}} Clamp({{T}}? min, {{T}}? max) => (min, max) switch
                {
                    (null, null) => this,
                    (null, { } hi) => _si > hi._si ? hi : this,
                    ({ } lo, null) => _si < lo._si ? lo : this,
                    ({ } lo, { } hi) => Clamp(lo, hi),
                };
                public {{T}} LowerLimitAt({{T}} limit) => _si > limit._si ? this : limit;
                public {{T}} UpperLimitAt({{T}} limit) => _si < limit._si ? this : limit;
                /// <summary>Rounds to a multiple of <paramref name="step"/> (midpoints to even, like Math.Round).</summary>
                public {{T}} RoundTo({{T}} step) => new(Math.Round(_si / step._si) * step._si);
                public {{T}} CeilingTo({{T}} step) => new(Math.Ceiling(_si / step._si) * step._si);
                public {{T}} FloorTo({{T}} step) => new(Math.Floor(_si / step._si) * step._si);
                public bool IsZero() => _si == 0;
                public bool IsNotZero() => !IsZero();
                public bool IsAboveZero() => _si > 0;
                public bool IsBelowZero() => _si < 0;
                /// <summary>Not NaN and not infinite, like EngineeringUnits.</summary>
                public bool HasValue() => !double.IsNaN(_si) && !double.IsInfinity(_si);
                public bool HasNoValue() => !HasValue();
                /// <summary>A {{T}} is never null - returns itself. The {{T}}? version returns Zero for null.</summary>
                public {{T}} IfNullSetToZero() => this;
                public static {{T}} Min({{T}} a, {{T}} b) => a._si <= b._si ? a : b;
                public static {{T}} Max({{T}} a, {{T}} b) => a._si >= b._si ? a : b;
                /// <summary>
                /// == is an exact double comparison, so 1 ft == 12 in can be false after rounding. Use this when the values
                /// come from different units. EngineeringUnits compares exactly (fractions) and needs no tolerance.
                /// </summary>
                public bool IsCloseTo({{T}} other, double relativeTolerance = 1e-12)
                    => _si == other._si || Math.Abs(_si - other._si) <= relativeTolerance * Math.Max(Math.Abs(_si), Math.Abs(other._si));
                public bool IsNaN() => double.IsNaN(_si);
                public bool IsInfinity() => double.IsInfinity(_si);

                // ---- Equality ----
                public bool Equals({{T}} other) => _si.Equals(other._si);
                public override bool Equals(object? obj) => obj is {{T}} other && Equals(other);
                public override int GetHashCode() => _si.GetHashCode();
                public int CompareTo({{T}} other) => _si.CompareTo(other._si);
                public int CompareTo(object? obj) => obj is {{T}} other ? CompareTo(other) : throw new ArgumentException($"Can't compare {{T}} with {obj?.GetType().Name ?? "null"}");

                // ---- Text ----
                /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
                public override string ToString() => ToString(null, null);
                public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
                public string ToString(string? format) => ToString(format, null);
                public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, {{U}}.SI.Symbol, format, formatProvider);
                /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
                public string ToString({{U}} unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

                /// <summary>
                /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
                /// stored in SI, so this is a display wrapper - it converts back to {{T}}, but math on it needs the {{T}} first.
                /// </summary>
                public QuantityInUnit<{{T}}> ToUnit({{U}} unit) => new(this, unit);

                /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
                [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
                public double AsSI => _si;

                /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
                public {{T}} ConvertToSI() => this;

            }

            /// <summary>Writes {"Value": si, "Unit": "{{q.Units[0].Symbol}}"}. Reads that (any unit of {{T}}, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
            public sealed class {{T}}JsonConverter : JsonConverter<{{T}}>
            {
                public override {{T}} Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
                    => {{T}}.FromSI(QuantityJson.Read(ref reader, "{{T}}", {{U}}.BySymbol));

                public override void Write(Utf8JsonWriter writer, {{T}} value, JsonSerializerOptions options)
                    => QuantityJson.Write(writer, value.SI, {{U}}.SI.Symbol);
            }

            public static partial class UnitMath
            {
                [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
                public static UnknownUnit Pow(this {{T}} value, int toPower) => new(Math.Pow(value.SI, toPower));

                [return: DimensionOf(nameof(value), Root = 2)]
                public static UnknownUnit Sqrt(this {{T}} value) => new(Math.Sqrt(value.SI));

                public static {{T}} Sum(this IEnumerable<{{T}}> values)
                {
                    double sum = 0;
                    foreach (var v in values) sum += v.SI;
                    return {{T}}.FromSI(sum);
                }

                public static {{T}} Average(this IEnumerable<{{T}}> values)
                {
                    double sum = 0; long count = 0;
                    foreach (var v in values) { sum += v.SI; count++; }
                    return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : {{T}}.FromSI(sum / count);
                }

                public static {{T}} Min(this IEnumerable<{{T}}> values) => Aggregate(values, Math.Min);
                public static {{T}} Max(this IEnumerable<{{T}}> values) => Aggregate(values, Math.Max);

                private static {{T}} Aggregate(IEnumerable<{{T}}> values, Func<double, double, double> pick)
                {
                    using var e = values.GetEnumerator();
                    if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
                    var result = e.Current.SI;
                    while (e.MoveNext()) result = pick(result, e.Current.SI);
                    return {{T}}.FromSI(result);
                }
            }
            """);

        return sb.ToString();
    }

    /// <summary>
    /// The {T}? members, in their own file in the global namespace: in EngineeringUnits they are instance members of the
    /// class, usable without "using EngineeringUnits;" (e.g. db.Input.Pressure!.Bar in a file that never names Pressure).
    /// Extension members in the global namespace are in scope everywhere, so that code keeps compiling.
    /// </summary>
    public static string NullableFile(QuantityDef q, IReadOnlyList<QuantityDef> aliases)
        => Header + """
            using System;
            using EngineeringUnits.Fast;
            using EngineeringUnits.Units.Fast;
            """ + "\n" + NullableExtensions(q, aliases);

    /// <summary>
    /// In EngineeringUnits a quantity is a class, so "{T}?" is the same type and has all its members. Here "{T}?" is
    /// Nullable&lt;{T}&gt;, which has none of them. These extension members put them back with EngineeringUnits' behaviour:
    /// reading a value from null throws (EngineeringUnits: NullReferenceException), helpers pass null through.
    /// </summary>
    private static string NullableExtensions(QuantityDef q, IReadOnlyList<QuantityDef> aliases)
    {
        var T = q.Name;
        var U = $"{T}Unit";
        var getters = q.Units.Where(u => u.Name != "SI").Select(u => u.Name)
            .Concat(q.Forwarders.Where(f => !f.IsFactory).Select(f => f.Member))
            .Distinct()
            .ToList();

        var sb = new StringBuilder();
        sb.AppendLine($$"""

            #pragma warning disable CS8629 // reading a value from a null {{T}}? is meant to throw, like EngineeringUnits
            /// <summary>The members of <see cref="{{T}}"/> on a <see cref="{{T}}"/>? - reading from null throws, like EngineeringUnits.</summary>
            public static class {{T}}NullableExtensions
            {
                extension({{T}}? quantity)
                {
                    public double SI => quantity.Value.SI;
                    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)] public double AsSI => quantity.Value.SI;
            """);

        foreach (var g in getters)
        {
            sb.AppendLine($"        public double {g} => quantity.Value.{g};");
        }

        // "Color Color": in a class with a property "public {T}? {T} { get; set; }", the name {T} means the PROPERTY
        // (its type {T}? is not {T}), so "{T}.FromSI(1)" looks for FromSI on {T}?. In EngineeringUnits the property type is
        // the class itself and C# picks the type. These hidden members make that code mean the same again.
        var hidden = "[System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]";
        sb.AppendLine($$"""

                    // ---- Static members reached through a property named after its type (see NullableExtensions in CodeGen) ----
                    {{hidden}} public {{T}} Zero => {{T}}.Zero;
                    {{hidden}} public {{T}} NaN => {{T}}.NaN;
                    {{hidden}} public {{T}} FromSI(double si) => {{T}}.FromSI(si);
                    {{hidden}} public {{T}} From(double value, {{U}} unit) => {{T}}.From(value, unit);
            """);
        var factories = q.Units.Where(u => u.Name != "SI").Select(u => "From" + u.Name)
            .Concat(q.Forwarders.Where(f => f.IsFactory).Select(f => f.Member));
        foreach (var name in factories)
        {
            sb.AppendLine($"        {hidden} public {T} {name}(double value) => {T}.{name}(value);");
        }

        sb.AppendLine($$"""
                }

                public static double As(this {{T}}? quantity, {{U}} unit) => quantity.Value.As(unit);
                /// <summary>"" for null, like Nullable&lt;T&gt;.ToString().</summary>
                public static string ToString(this {{T}}? quantity, string? format) => quantity is { } q ? q.ToString(format) : "";
                public static string ToString(this {{T}}? quantity, IFormatProvider formatProvider) => quantity is { } q ? q.ToString(formatProvider) : "";
                public static string ToString(this {{T}}? quantity, string? format, IFormatProvider? formatProvider) => quantity is { } q ? q.ToString(format, formatProvider) : "";
                public static {{T}}? ConvertToSI(this {{T}}? quantity) => quantity;
                public static string ToString(this {{T}}? quantity, {{U}} unit, string? format = null, IFormatProvider? formatProvider = null)
                    => quantity is { } q ? q.ToString(unit, format, formatProvider) : "";
            """);

        foreach (var alias in aliases)
        {
            sb.AppendLine($$"""
                    public static double As(this {{T}}? quantity, {{alias.Name}}Unit unit) => quantity.Value.As(unit);
                    public static string ToString(this {{T}}? quantity, {{alias.Name}}Unit unit, string? format = null, IFormatProvider? formatProvider = null)
                        => quantity is { } q ? q.ToString(unit, format, formatProvider) : "";
                """);
        }

        sb.AppendLine($$"""

