    public static string UnitClass(QuantityDef q)
    {
        var U = $"{q.Name}Unit";
        var sb = new StringBuilder(Header);
        sb.AppendLine($$"""
            using System.Collections.Generic;
            using System.Linq;
            using EngineeringUnits.Fast;

            namespace EngineeringUnits.Units.Fast;

            /// <summary>The units of <see cref="{{q.Name}}"/>. SI = value * Factor + Offset.</summary>
            [UnitDimension({{q.Dim.AttributeArgs}})]   // lets the analyzer check a unit against a value ([SameDimension])
            public sealed class {{U}} : UnitTypebase
            {
                private {{U}}(string name, string symbol, double multiplier, double divisor, double offset)
                    : base(name, symbol, multiplier, divisor, offset) { }

            """);

        foreach (var u in q.Units)
        {
            var exact = u.ExactOffset.IsZero ? $"{u.ExactFactor}" : $"{u.ExactFactor}, offset {u.ExactOffset}";
            sb.AppendLine($"    /// <summary>[{System.Security.SecurityElement.Escape(u.Symbol)}] exact factor {exact}</summary>");
            sb.AppendLine($"    public static readonly {U} {u.Name} = new({Str(u.Name)}, {Str(u.Symbol)}, {Num(u.Multiplier)}, {Num(u.Divisor)}, {Num(u.Offset)});");
        }

        sb.AppendLine($$"""

                /// <summary>All units, SI first.</summary>
                public static readonly IReadOnlyList<{{U}}> All = new[] { {{string.Join(", ", q.Units.Select(u => u.Name))}} };

                internal static readonly Dictionary<string, {{U}}?> BySymbol = UnitLookup.BySymbol(All);
            }
            """);

        return sb.ToString();
    }

    public static string NumberExtensions(QuantityDef q)
    {
        var T = q.Name;
        var sb = new StringBuilder(Header);
        sb.AppendLine($$"""
            using EngineeringUnits.Fast;

            namespace EngineeringUnits.NumberExtensions.NumberTo{{T}}.Fast;

            public static class NumberTo{{T}}Extensions
            {
            """);

        foreach (var receiver in new[] { "double", "int" })
        {
            sb.AppendLine($"    extension({receiver} value)");
            sb.AppendLine("    {");
            foreach (var u in q.Units.Where(u => u.Name != "SI"))
                sb.AppendLine($"        public {T} {u.Name} => {T}.From{u.Name}(value);");
            sb.AppendLine("    }");
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

    public static string Constants(List<ConstantDef> constants)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("""
            // Constants without a named quantity are UnknownUnit values marked with their dimension; the analyzer trusts the attribute
            #pragma warning disable EUF0007

            namespace EngineeringUnits.Fast;

            /// <summary>Physical constants, same values as EngineeringUnits.Constants.</summary>
            public static class Constants
            {
            """);

        foreach (var c in constants)
        {
            if (c.QuantityName is not null)
                sb.AppendLine($"    public static readonly {c.QuantityName} {c.Name} = {c.QuantityName}.FromSI({Num(c.SI)});");
            else
            {
                sb.AppendLine($"    [UnitDimension({c.Dim.AttributeArgs})]");
                sb.AppendLine($"    public static readonly UnknownUnit {c.Name} = new({Num(c.SI)});");
            }
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

